<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import NavSidebar from './components/NavSidebar.vue'
import MobileNav from './components/MobileNav.vue'
import TopBar from './components/TopBar.vue'
import MetricCard from './components/MetricCard.vue'
import StatusBadge from './components/StatusBadge.vue'
import EmptyState from './components/EmptyState.vue'
import LoadState from './components/LoadState.vue'
import CapabilityChips from './components/CapabilityChips.vue'
import PageIntro from './components/PageIntro.vue'
import DetailDrawer from './components/DetailDrawer.vue'
import StructuredDetail from './components/StructuredDetail.vue'
import ConfirmDialog from './components/ConfirmDialog.vue'
import Pagination from './components/Pagination.vue'
import ProviderWizard from './components/ProviderWizard.vue'
import { get, post } from './services/api'
import { useAsyncTask } from './services/async-task'
import { parseRouteState, serializeRouteState } from './services/route-state'
import { settleRecord } from './services/settle'
import { overviewHealthLabel, overviewTone } from './services/overview'
import { filterModels, providerOperationalLabel, providerOperationalTone, selectableModelIds, type CapabilityFilter } from './services/catalog'
import type { ProviderRegistryResponse } from './services/provider-registry'
import { autoExclusionReasons, evidenceGroups, governanceCounts } from './services/governance'
import type { Model, Overview, OverviewStatus, PageKey, Provider, ExternalIntegration, Reviewer, ReviewerCandidates, Review, ReviewStats, Shadow, Knowledge, ProbeBatchStatus, ProbeBatchHistory, ReviewBatch, ShadowBatch } from './types'

type Row = Record<string, unknown>
type ListResponse = { items?: Row[]; files?: string[]; requests?: Row[]; accounts?: Row[] }
const labels: Record<PageKey, string> = { overview:'总览', resources:'资源池', integrations:'外部集成', catalog:'模型目录', routing:'路由中心', governance:'能力治理', reviews:'教师复盘', knowledge:'路由知识', shadow:'影子验证', logs:'调用与告警', accounts:'账号额度', snapshots:'版本快照', operations:'运维控制', system:'系统状态' }
const initialRoute = parseRouteState(window.location.search)
const page = ref<PageKey>(initialRoute.page); const authenticated = ref(false); const loading = ref(true); const loadingStatus = ref<'loading'|'timeout'|'error'|'empty'>('loading'); const refreshing = ref(false); const error = ref(''); const toast = ref('')
const username = ref(''); const password = ref(''); const loginBusy = ref(false); const loginError = ref('')
const models = ref<Model[]>([]); const providers = ref<Provider[]>([]); const reviewer = ref<Reviewer>({ model:'', provider:'', consecutive_failures:0 }); const candidates = ref<ReviewerCandidates>({ items:[], probe_candidates:[], eligible:0, probeable:0, excluded:0, reasons:{}, capability_probe_available:true }); const reviewStats = ref<ReviewStats>({ pending:0, processing:0, reviewed:0, failed:0, skipped:0 }); const reviews = ref<Review[]>([]); const shadows = ref<Shadow[]>([]); const shadowBatches = ref<ShadowBatch[]>([]); const knowledge = ref<Knowledge[]>([])
const overview = ref<Overview | null>(null); const integration = ref<ExternalIntegration>({}); const providerRegistry = ref<Provider[]>([]); const credentialKeyReady = ref(false); const editingProvider = ref<Provider | null>(null); const snapshotDetail = ref<Row | null>(null); const quotaStatus = ref<Row>({}); const quotaHistory = ref<Row[]>([]); const routes = ref<Row[]>([]); const governance = ref<Row[]>([]); const recent = ref<Row[]>([]); const alerts = ref<Row[]>([]); const snapshots = ref<string[]>([]); const accounts = ref<Row[]>([]); const quota = ref<Row[]>([]); const diagnostics = ref<Row>({}); const watchdog = ref<Row>({}); const status = ref<Row>({}); const consistency = ref<Row>({}); const regression = ref<Row>({}); const reviewTotal = ref(0); const reviewOffset = ref(0); const reviewLimit = 50; const reviewBatches = ref<ReviewBatch[]>([]); const reviewStatusFilter = ref(''); const auditStatusFilter = ref(''); const auditProviderFilter = ref(''); const auditMinLatency = ref(''); const auditMaxLatency = ref(''); const alertStatusFilter = ref(''); const alertLevelFilter = ref(''); const reviewDetailLoading = ref(false); const operationResult = ref<Row>({})
const query = ref(initialRoute.query); const statusFilter = ref(initialRoute.status); const providerFilter = ref(initialRoute.provider); const capabilityFilter = ref<CapabilityFilter>('all'); const knowledgeStatusFilter = ref(''); const selectedKnowledgeId = ref(''); const selectedReviewId = ref(''); const selectedCandidateModel = ref(''); const selected = ref<Row | Model | null>(null); const selectedModelIds = ref<string[]>([]); const currentPage = ref(initialRoute.currentPage); const pageSize = 30
const probeBatch = ref<ProbeBatchStatus | null>(null); const probeHistory = ref<ProbeBatchHistory[]>([]); const probeBatchBusy = ref(false); const providerWizardOpen = ref(false); const explainInput = ref('{\n  "model": "auto",\n  "messages": [{"role": "user", "content": "请说明你的能力"}],\n  "tools": []\n}'); const explainResult = ref<Row | null>(null); const explainBusy = ref(false); const governancePreview = ref<Row | null>(null); const governanceBusy = ref(false); const reviewerTest = ref<Row | null>(null); const reviewerTestBusy = ref(false)
const confirmOpen = ref(false); const confirmBusy = ref(false); const confirmTitle = ref(''); const confirmDetail = ref(''); const confirmLabel = ref('确认'); const confirmDanger = ref(false); const reviewRunning = ref(false); const reviewPruning = ref(false); const paletteOpen = ref(false); const paletteQuery = ref(''); const mobileNav = ref<InstanceType<typeof MobileNav> | null>(null); const paletteItems = computed(() => Object.entries(labels).filter(([key,label]) => !paletteQuery.value || `${key} ${label}`.toLowerCase().includes(paletteQuery.value.toLowerCase()))); let pendingAction: (() => Promise<void>) | null = null
const providerById = computed(() => new Map(providers.value.map(provider => [provider.id, provider]))); const governanceStateCounts = computed(() => governanceCounts(governance.value)); const selectedDomainModel = computed(() => { const row = selected.value as Row | null; if (!row) return null; if (row.model && typeof row.model === 'object') return row.model as unknown as Model; return typeof row.id === 'string' && typeof row.provider === 'string' ? row as unknown as Model : null }); const selectedModelProvider = computed(() => { const model = selectedDomainModel.value; return model?.provider ? providerById.value.get(model.provider) : undefined }); const selectedModelReasons = computed(() => { const model = selectedDomainModel.value; return model ? autoExclusionReasons(model, selectedModelProvider.value) : [] }); const selectedModelEvidence = computed(() => { const model = selectedDomainModel.value; return model ? evidenceGroups(model) : [] }); const activeModels = computed(() => models.value.filter(m => m.status === 'active')); const autoModels = computed(() => models.value.filter(m => m.auto_routable)); const filteredModels = computed(() => filterModels(models.value, query.value, providerFilter.value, statusFilter.value, capabilityFilter.value)); const pagedModels = computed(() => filteredModels.value.slice((currentPage.value - 1) * pageSize, currentPage.value * pageSize)); const selectedModels = computed(() => models.value.filter(model => selectedModelIds.value.includes(`${model.provider}/${model.id}`))); const allPageSelected = computed(() => pagedModels.value.length > 0 && pagedModels.value.every(model => selectedModelIds.value.includes(`${model.provider}/${model.id}`)))
function message(e: unknown, fallback: string) { return (e as { message?: string }).message || fallback }
const bootTask = useAsyncTask<void>(() => false)
let activeRequestSignal: AbortSignal | undefined
let bootSequence = 0
function getWithSignal<T>(path: string) { return get<T>(path, activeRequestSignal ? { signal: activeRequestSignal } : {}) }
async function logout() { try { await post('/api/admin/logout'); authenticated.value = false; username.value = ''; password.value = ''; page.value = 'overview' } catch (e) { error.value = message(e, '退出失败') } }
async function loadProviderRegistry(){const result=await getWithSignal<ProviderRegistryResponse>('/api/admin/provider-registry');providerRegistry.value=result.items||[];credentialKeyReady.value=result.credential_key_configured}
function openProviderWizard(provider?:Provider){editingProvider.value=provider||null;providerWizardOpen.value=true}
function closeProviderWizard(){providerWizardOpen.value=false;editingProvider.value=null}
async function providerSaved(messageText:string){closeProviderWizard();toast.value=messageText;await boot()}
function providerRecord(id:string){return providerRegistry.value.find(item=>item.id===id)}
async function providerRegistryAction(provider:Provider,action:'enable'|'disable'|'delete'){
 const labels={enable:'启用',disable:'停用',delete:'删除'};const destructive=action==='delete';const detail=destructive?`删除 ${provider.name||provider.id} 后，其历史模型会标记为 stale 并立即退出 Auto；密文凭证将被永久删除。`:`${labels[action]} ${provider.name||provider.id}？`;
 confirmAction(`${labels[action]} Provider`,detail,async()=>{await post(`/api/admin/provider-registry/${action}?id=${encodeURIComponent(provider.id)}`);toast.value=`Provider 已${labels[action]}`;await boot()},destructive,labels[action])
}
async function loadLocalQuota(){try{const result=await getWithSignal<{available?:boolean;report?:import('./types').LocalQuotaReport;checked_at?:string;error?:string}>('/api/admin/integrations/freellmapi/local-quota');if(result.report) integration.value={...integration.value,local_quota:result.report,local_quota_state:result.error?'stale':'available',local_quota_error:result.error,local_quota_checked_at:result.checked_at};else integration.value={...integration.value,local_quota_state:result.error||'unavailable',local_quota_error:result.error,local_quota_checked_at:result.checked_at}}catch(e){error.value=message(e,'FreeLLMAPI 本地额度读取失败')}}
async function refreshLocalQuota(){try{const result=await post<{ok?:boolean;report?:import('./types').LocalQuotaReport;error?:string}>('/api/admin/integrations/freellmapi/local-quota/refresh');if(result.report) integration.value={...integration.value,local_quota:result.report,local_quota_state:'available',local_quota_error:''};if(result.ok===false) throw new Error(`本地额度刷新失败：${result.error||'local_database_unavailable'}`);toast.value='FreeLLMAPI 本地额度已刷新';await loadPage()}catch(e){error.value=message(e,'FreeLLMAPI 本地额度刷新失败')}}
async function integrationAction(path:string, body:unknown = {}) { try { const result=await post<Row>(path,body); const state=result?.state as Row|undefined; if(state) integration.value={...integration.value,...state}; toast.value='FreeLLMAPI 集成状态已更新'; await boot() } catch(e) { error.value=message(e,'FreeLLMAPI 集成操作失败') } }
async function probeIntegration(){await integrationAction('/api/admin/integrations/freellmapi/probe')}
async function authorizeIntegration(){confirmAction('授权接入 FreeLLMAPI','授权后星枢将只读读取 FreeLLMAPI 本地 SQLite/WAL 中的模型预算、模型使用量、速率窗口和 Provider 额度观测；不会修改 FreeLLMAPI，也不读取下游 Key、Cookie、Prompt 或 Response。生产路由仍需单独开启。',async()=>{await integrationAction('/api/admin/integrations/freellmapi/authorize',{route_enabled:false})})}
async function revokeIntegration(){confirmAction('撤销 FreeLLMAPI 接入','撤销后星枢停止访问该实例，历史模型快照保留但不再参与路由。',async()=>{await integrationAction('/api/admin/integrations/freellmapi/revoke')},true,'撤销接入')}
async function toggleIntegrationRoute(){const enabled=integration.value.route_enabled!==true;confirmAction(enabled?'允许 FreeLLMAPI 参与生产路由':'禁止 FreeLLMAPI 参与生产路由',enabled?'开启后 FreeLLMAPI 模型可以被星枢原有路由策略选中。':'关闭后保留同步和观察，但不再发起 FreeLLMAPI 生产调用。',async()=>{await integrationAction('/api/admin/integrations/freellmapi/route',{enabled})},!enabled,enabled?'开启生产路由':'关闭生产路由')}
async function syncIntegration(){await integrationAction('/api/admin/integrations/freellmapi/sync')}

async function login() { loginBusy.value = true; loginError.value = ''; try { await post('/api/admin/login', new URLSearchParams({ username:username.value, password:password.value })); authenticated.value = true; await boot() } catch (e) { loginError.value = message(e, '账号或密码错误') } finally { loginBusy.value = false } }
async function loadCore() { const result = await settleRecord({ overview: getWithSignal<Overview>('/api/admin/overview'), cat: getWithSignal<{ models:Model[] }>('/api/admin/models'), ps: getWithSignal<{ providers:Provider[] }>('/api/admin/providers'), rv: getWithSignal<Reviewer>('/api/admin/reviewer'), stats: getWithSignal<{ stats:ReviewStats }>('/api/admin/reviews/stats') }); const values = result.values; if(values.overview) overview.value=values.overview; if(values.cat) models.value=values.cat.models||[]; if(values.ps) providers.value=values.ps.providers||[]; if(values.rv) reviewer.value=values.rv; if(values.stats) reviewStats.value=values.stats.stats; const unauthorized = result.errors.find(item => (item.error as { kind?: string }).kind === 'unauthorized'); if(unauthorized) throw unauthorized.error; if(result.errors.length) error.value = `部分核心数据暂不可用：${result.errors.map(item => item.key).join('、')}` }
async function loadPage() { const p=page.value; if(p==='resources'){await loadProviderRegistry();return} if(p==='integrations'){const result=await getWithSignal<{items?:Row[]}>('/api/admin/integrations/freellmapi/status');integration.value=(result.items&&result.items[0])||{};if(integration.value.authorized) await loadLocalQuota();return} if(p==='catalog') await loadProbeHistory(); if(p==='reviews'){const result=await settleRecord({c:getWithSignal<ReviewerCandidates>('/api/admin/reviewer/candidates'),r:getWithSignal<{items:Review[];total:number;offset:number;limit:number}>(`/api/admin/reviews?limit=${reviewLimit}&offset=${reviewOffset.value}`),b:getWithSignal<{items:ReviewBatch[]}>('/api/admin/reviews/batches')});if(result.values.c)candidates.value=result.values.c;if(result.values.r){reviews.value=result.values.r.items||[];reviewTotal.value=result.values.r.total||0}if(result.values.b)reviewBatches.value=result.values.b.items||[];if(result.errors.length)error.value=`复盘页面部分数据暂不可用：${result.errors.map(item=>item.key).join('、')}`} if(p==='routing')routes.value=(await getWithSignal<ListResponse>('/api/admin/routing/explain')).items||[]; if(p==='governance')governance.value=(await getWithSignal<ListResponse>('/api/admin/governance')).items||[]; if(p==='knowledge'){const result=await settleRecord({knowledge:getWithSignal<ListResponse>(`/api/admin/knowledge${knowledgeStatusFilter.value?`?status=${encodeURIComponent(knowledgeStatusFilter.value)}`:''}`),reviews:getWithSignal<{items:Review[];total:number}>(`/api/admin/reviews?limit=${reviewLimit}&offset=0`)});if(result.values.knowledge)knowledge.value=result.values.knowledge.items as unknown as Knowledge[]||[];if(result.values.reviews)reviews.value=result.values.reviews.items||[];if(result.errors.length)error.value=`知识页面部分数据暂不可用：${result.errors.map(item=>item.key).join('、')}`} if(p==='shadow'){const result=await settleRecord({items:getWithSignal<ListResponse>('/api/admin/shadow'),batches:getWithSignal<{items:ShadowBatch[]}>('/api/admin/shadow/batches')});if(result.values.items)shadows.value=result.values.items.items as unknown as Shadow[]||[];if(result.values.batches)shadowBatches.value=result.values.batches.items||[];if(result.errors.length)error.value=`Shadow 页面部分数据暂不可用：${result.errors.map(item=>item.key).join('、')}`} if(p==='logs'){const params=new URLSearchParams();if(auditProviderFilter.value)params.set('provider',auditProviderFilter.value);if(auditStatusFilter.value)params.set('status',auditStatusFilter.value);if(auditMinLatency.value)params.set('min_latency_ms',auditMinLatency.value);if(auditMaxLatency.value)params.set('max_latency_ms',auditMaxLatency.value);const suffix=params.toString()?`?${params}`:'';const r=await getWithSignal<ListResponse & {total?:number}>(`/api/admin/recent${suffix}`);recent.value=r.requests||[]} if(p==='accounts'){const result=await settleRecord({accounts:getWithSignal<ListResponse>('/api/admin/accounts'),quota:getWithSignal<ListResponse>('/api/admin/quota'),history:getWithSignal<ListResponse>('/api/admin/quota/history'),status:getWithSignal<Row>('/api/admin/quota/status'),integration:getWithSignal<{items?:Row[]}>('/api/admin/integrations/freellmapi/status')});if(result.values.accounts)accounts.value=result.values.accounts.accounts||[];if(result.values.quota)quota.value=result.values.quota.items||[];if(result.values.history)quotaHistory.value=result.values.history.items||[];if(result.values.status)quotaStatus.value=result.values.status;if(result.values.integration){integration.value=(result.values.integration.items&&result.values.integration.items[0])||{};if(integration.value.authorized)await loadLocalQuota()}} if(p==='snapshots')snapshots.value=(await getWithSignal<{files:string[]}>('/api/admin/snapshots')).files||[]; if(p==='system'){const result=await settleRecord({status:getWithSignal<Row>('/api/admin/status'),consistency:getWithSignal<Row>('/api/admin/consistency'),regression:getWithSignal<Row>('/api/admin/regression'),diagnostics:getWithSignal<Row>('/api/admin/diagnostics'),watchdog:getWithSignal<Row>('/api/admin/watchdog')});if(result.values.status)status.value=result.values.status;if(result.values.consistency)consistency.value=result.values.consistency;if(result.values.regression)regression.value=result.values.regression;if(result.values.diagnostics)diagnostics.value=result.values.diagnostics;if(result.values.watchdog)watchdog.value=result.values.watchdog;if(result.errors.length)error.value=`系统页面部分数据暂不可用：${result.errors.map(item=>item.key).join('、')}`} if(p==='operations'){const params=new URLSearchParams();if(alertStatusFilter.value)params.set('status',alertStatusFilter.value);if(alertLevelFilter.value)params.set('level',alertLevelFilter.value);const suffix=params.toString()?`?${params}`:'';alerts.value=(await getWithSignal<ListResponse>(`/api/admin/alerts${suffix}`)).items||[]} }
let loadingTimer: ReturnType<typeof setTimeout> | undefined
async function boot(){const sequence=++bootSequence;loading.value=true;loadingStatus.value='loading';error.value='';if(loadingTimer)clearTimeout(loadingTimer);loadingTimer=setTimeout(()=>{if(sequence===bootSequence&&loading.value)loadingStatus.value='timeout'},3000);try{await bootTask.run(async signal=>{activeRequestSignal=signal;try{await loadCore();authenticated.value=true;await loadPage()}finally{if(activeRequestSignal===signal)activeRequestSignal=undefined}})}catch(e){const x=e as {status?:number;kind?:string};if(sequence!==bootSequence)return;if(x.status===401||x.kind==='unauthorized')authenticated.value=false;if(x.kind!=='aborted'){loadingStatus.value='error';error.value=message(e,'控制台暂时无法读取数据')}}finally{if(sequence===bootSequence){loading.value=false;if(loadingTimer)clearTimeout(loadingTimer)}}}
async function navigate(next:PageKey){page.value=next;query.value='';statusFilter.value='';providerFilter.value='';currentPage.value=1;syncRouteState(false);await boot()}; async function refresh(){refreshing.value=true;await boot();refreshing.value=false}
async function sync(){refreshing.value=true;try{const result=await post<Row>('/api/admin/sync');operationResult.value=result||{};const results=result?.results as Row|undefined;const failed=results?Object.values(results).filter(item=>{const row=item as Row;return row.error_type||row.error}).length:0;toast.value=results?`Provider 同步完成：${Object.keys(results).length} 项${failed?`，失败 ${failed}`:''}`:'Provider 目录同步完成';await boot()}catch(e){error.value=message(e,'同步失败')}finally{refreshing.value=false}}
async function execute(path:string, body?: unknown): Promise<boolean> { try { const result=await post<Row>(path, body); operationResult.value=result||{}; const detail=result?.results?`：${Object.keys(result.results as Row).length} 项结果`:result?.created!==undefined?`：创建 ${result.created}`:result?.reviewed!==undefined?`：复盘 ${result.reviewed}`:result?.ok===true?'':'操作已完成'; toast.value=`操作完成${detail}`; await boot(); return true } catch (e) { toast.value = ''; error.value = message(e, '操作失败'); return false } }
async function handleAlert(id:string, action:string){try{await post('/api/admin/alerts/action',{id,action,note:`控制台操作：${action}`});toast.value=`告警已${action==='acknowledge'?'确认':action==='resolve'?'恢复':'更新'}`;await boot()}catch(e){error.value=message(e,'告警处理失败')}}
function confirmAction(title: string, detail: string, action: () => Promise<void>, danger = false, label = '确认执行') { confirmTitle.value = title; confirmDetail.value = detail; confirmDanger.value = danger; confirmLabel.value = label; pendingAction = action; confirmOpen.value = true }
async function acceptConfirm() { if (!pendingAction) return; confirmBusy.value = true; try { await pendingAction() } finally { confirmBusy.value = false; confirmOpen.value = false; pendingAction = null } }
function cancelConfirm() { if (!confirmBusy.value) { confirmOpen.value = false; pendingAction = null } }
function operate(path: string, title = '确认操作', detail = '该操作会改变运行状态，请确认继续。', danger = false, label = '确认执行') { confirmAction(title, detail, async () => { await execute(path) }, danger, label) }
async function runReview() { if (reviewRunning.value) return; reviewRunning.value = true; toast.value = '正在运行复盘批次…'; try { const ok = await execute('/api/admin/reviews/run?limit=20&include_today=true'); if (ok) toast.value = '复盘批次已完成' } finally { reviewRunning.value = false } }
async function pruneReviews() { if (reviewPruning.value) return; reviewPruning.value = true; try { await execute('/api/admin/reviews/prune?days=30') } finally { reviewPruning.value = false } }
async function validateKnowledge(id: string, success: boolean) { await execute('/api/admin/knowledge/validate', { id, validation_id: `manual-${Date.now()}`, success, failure_cause: success ? '' : '人工验证失败', note: success ? '控制台人工验证通过' : '控制台人工否决' }) }
async function decideKnowledge(id: string, status: string) { await execute('/api/admin/knowledge/decision', { id, status, note: `控制台操作：${status}` }) }
async function runShadow(knowledgeId: string, reviewId: string, candidateModel = '') { await execute('/api/admin/shadow/run', { knowledge_id: knowledgeId, review_id: reviewId, candidate_model: candidateModel || undefined }) }
async function restoreKnowledge(id: string) { await execute('/api/admin/knowledge/restore', { id, status: 'validated', note: '控制台重新验证并恢复' }) }
async function startShadowBatch() { if (!selectedKnowledgeId.value || !selectedReviewId.value) { error.value = '必须明确选择 Knowledge 和源复盘记录'; return }; const result = await post<{batch_id:string}>('/api/admin/shadow/batches/start', { knowledge_id: selectedKnowledgeId.value, review_ids: [selectedReviewId.value], candidate_model: selectedCandidateModel.value || undefined }); toast.value = `Shadow 批次已创建：${result.batch_id}`; await boot() }
async function stopShadowBatch(id:string) { await execute('/api/admin/shadow/batches/stop',{batch_id:id}) }
async function retryShadowBatch(id:string) { await execute('/api/admin/shadow/batches/retry',{batch_id:id}) }
async function openSnapshotDetail(name:string){try{snapshotDetail.value=await getWithSignal<Row>(`/api/admin/snapshots/detail?name=${encodeURIComponent(name)}`)}catch(e){error.value=message(e,'快照详情读取失败')}}
async function restoreSnapshot(name: string) { await execute(`/api/admin/snapshots/restore?name=${encodeURIComponent(name)}`) }
async function choose(m:Model){try{await post('/api/admin/reviewer/select',{model:m.id,provider:m.provider});reviewer.value={...reviewer.value,model:m.id,provider:m.provider};toast.value=`已选择 ${m.id} 作为教师模型`}catch(e){error.value=message(e,'教师模型保存失败')}}
async function probe(m:Model){try{await post(`/api/admin/probe?provider=${encodeURIComponent(m.provider)}&model=${encodeURIComponent(m.id)}`);toast.value=`${m.id} 能力探测完成`;await boot()}catch(e){error.value=message(e,'能力探测失败')}}
function toggleModel(model: Model) { const id = `${model.provider}/${model.id}`; selectedModelIds.value = selectedModelIds.value.includes(id) ? selectedModelIds.value.filter(item => item !== id) : selectableModelIds([model], [...selectedModelIds.value, id]) }
function togglePageModels() { const pageIds = pagedModels.value.map(model => `${model.provider}/${model.id}`); selectedModelIds.value = allPageSelected.value ? selectedModelIds.value.filter(id => !pageIds.includes(id)) : selectableModelIds(pagedModels.value, [...selectedModelIds.value, ...pageIds]) }
async function loadProbeHistory() { try { const result = await getWithSignal<{ items: ProbeBatchHistory[] }>('/api/admin/probe/batch/history'); probeHistory.value = result.items || [] } catch (e) { error.value = message(e, '探测历史读取失败') } }
async function explainRoute() { if (explainBusy.value) return; explainBusy.value = true; try { const input = JSON.parse(explainInput.value) as Row; explainResult.value = await post<Row>('/api/admin/routing/explain', input); toast.value = '路由 Explain 已更新' } catch (e) { error.value = message(e, '路由 Explain 输入必须是有效 JSON') } finally { explainBusy.value = false } }
async function testReviewer() { if (reviewerTestBusy.value || !reviewer.value.model || !reviewer.value.provider) return; reviewerTestBusy.value = true; try { reviewerTest.value = await post<Row>('/api/admin/reviewer/test', { provider: reviewer.value.provider, model: reviewer.value.model }); toast.value = reviewerTest.value.structured_output === true ? '教师连接和 JSON 能力通过' : '教师连接测试未通过' } catch (e) { error.value = message(e, '教师连接测试失败') } finally { reviewerTestBusy.value = false } }
async function openReviewDetail(review: Review) { reviewDetailLoading.value = true; try { selected.value = await getWithSignal<Row>(`/api/admin/reviews/detail?id=${encodeURIComponent(review.id)}`) } catch (e) { error.value = message(e, '复盘详情读取失败') } finally { reviewDetailLoading.value = false } }
async function previewGovernance(model: Model, allow: boolean) { if (governanceBusy.value) return; governanceBusy.value = true; try { governancePreview.value = await post<Row>('/api/admin/governance/rules/preview', { changes: [{ key: `${model.provider}/${model.id}`, allow }] }); } catch (e) { error.value = message(e, '治理变更预览失败') } finally { governanceBusy.value = false } }
async function applyGovernance() { const change = (governancePreview.value?.changes as Row[] || [])[0]; if (!change || change.changed !== true) { error.value = '没有需要应用的治理变更'; return } confirmAction('确认治理规则变更？', `将把 ${value(change, 'key')} 设置为 ${change.after ? '允许 Auto' : '拒绝 Auto'}。`, async () => { await execute('/api/admin/governance/rules/apply', { changes: [{ key: value(change, 'key'), allow: change.after === true }] }) }) }
async function runProbeBatch() { if (probeBatchBusy.value || !selectedModels.value.length) return; probeBatchBusy.value = true; try { const result = await post<{ job_id: string }>('/api/admin/probe/batch', { models: selectedModels.value.map(model => ({ provider: model.provider, model: model.id })) }); for (let i = 0; i < 120; i += 1) { probeBatch.value = await getWithSignal<ProbeBatchStatus>(`/api/admin/probe/batch/status?job_id=${encodeURIComponent(result.job_id)}`); if (probeBatch.value.status === 'completed') break; await new Promise(resolve => setTimeout(resolve, 500)) } await loadProbeHistory(); selectedModelIds.value = []; await boot(); toast.value = probeBatch.value?.status === 'completed' ? '批量能力探测完成' : '批量探测仍在运行，请稍后刷新' } catch (e) { error.value = message(e, '批量能力探测失败') } finally { probeBatchBusy.value = false } }
function syncRouteState(replace = true) {
  const next = serializeRouteState({ page: page.value, query: query.value, status: statusFilter.value, provider: providerFilter.value, currentPage: currentPage.value })
  const url = `${window.location.pathname}${next}`
  if (replace) window.history.replaceState(null, '', url)
  else window.history.pushState(null, '', url)
}
function restoreRouteState() {
  const next = parseRouteState(window.location.search)
  page.value = next.page; query.value = next.query; statusFilter.value = next.status; providerFilter.value = next.provider; currentPage.value = next.currentPage
}
function tone(s:string){return s==='active'||s==='reviewed'||s==='ok'?'green':s==='unknown'||s==='pending'||s==='processing'?'amber':s==='failed'||s==='disabled'?'red':'muted'}
function value(row:Row,key:string){const v=row[key];return v===null||v===undefined||v===''?'—':String(v)}
function formatTokens(value: unknown){if(value===null||value===undefined||value==='')return '暂无数据';const n=Number(value);if(!Number.isFinite(n))return String(value);if(n>=1000000)return `${(n/1000000).toFixed(n>=10000000?0:1)}M`;if(n>=1000)return `${(n/1000).toFixed(n>=100000?0:1)}K`;return Math.round(n).toLocaleString()}
function selectedTitle(){const row=selected.value as Row|null;return row?value(row,'id')!=='—'?value(row,'id'):value(row,'model')!=='—'?value(row,'model'):value(row,'file'):'详情'}
function openPalette(){paletteQuery.value='';paletteOpen.value=true}
function closePalette(){paletteOpen.value=false}
function choosePalette(key:string){paletteOpen.value=false;void navigate(key as PageKey)}
function onKeyDown(event:KeyboardEvent){if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();openPalette();return};if(event.key==='Escape'&&paletteOpen.value){event.preventDefault();closePalette()}}
function governanceModel(row: Row): Model | null { return row.model && typeof row.model === 'object' ? row.model as unknown as Model : null }
function reviewForKnowledge(item: Knowledge) { return reviews.value.find(review => item.source_review_ids?.includes(review.id) && review.review_status === 'reviewed') }
function runKnowledgeShadow(item: Knowledge) { const review = reviewForKnowledge(item); if (!review) { selectedKnowledgeId.value = item.id; navigate('reviews'); error.value = '该 Knowledge 没有已复盘源记录，请先选择明确的源记录'; return } selectedKnowledgeId.value = item.id; selectedReviewId.value = review.id; selectedCandidateModel.value = item.recommended_model; confirmAction('运行 Shadow 验证？', `Knowledge=${item.id}，源复盘=${review.id}，候选=${item.recommended_model}。仅执行无副作用回放。`, () => runShadow(item.id, review.id, item.recommended_model)) }
watch([page, query, statusFilter, providerFilter, currentPage], () => syncRouteState())
function onPopState() { restoreRouteState(); void boot() }
onMounted(() => { window.addEventListener('popstate', onPopState); window.addEventListener('keydown', onKeyDown); void boot() })
onBeforeUnmount(() => { window.removeEventListener('popstate', onPopState); window.removeEventListener('keydown', onKeyDown); bootTask.cancel() })
</script>
<template>
  <main v-if="!authenticated" class="login-screen"><div class="login-glow"></div><section class="login-card glass-card"><div class="brand login-brand"><div class="brand-mark">✦</div><div><strong>星枢</strong><span>模型路由 · 治理控制面</span></div></div><span class="kicker">SECURE ADMIN ACCESS</span><h1>进入控制面</h1><p>管理资源、模型能力与复盘学习闭环。</p><form @submit.prevent="login"><label>管理员账号<input v-model="username" required autocomplete="username" /></label><label>管理员密码<input v-model="password" required type="password" autocomplete="current-password" /></label><button class="button button-primary login-button" :disabled="loginBusy">{{ loginBusy?'验证中…':'登录控制台 →' }}</button><small v-if="loginError" class="login-error">{{ loginError }}</small></form></section></main>
  <div v-else class="app-shell"><NavSidebar :page="page" @navigate="navigate" /><MobileNav ref="mobileNav" :page="page" @navigate="navigate" /><main class="main-content"><TopBar :eyebrow="labels[page]" :title="labels[page]" :refreshing="refreshing" @menu="mobileNav?.show($event)" @refresh="refresh" @logout="logout" /><div class="content-container"><div v-if="error" class="alert alert-error"><b>操作失败</b><span>{{ error }}</span><button class="button button-small" @click="boot">重试</button></div><LoadState v-if="loading" :state="loadingStatus" message="" @retry="boot" />
    <template v-else>
      <section v-if="page==='overview'" class="page-stack"><PageIntro kicker="COMMAND DECK" title="控制面总览" description="从健康、资源、路由和学习闭环，快速确认生产系统当前是否可用。"><template #actions><button class="button button-primary" @click="sync">同步目录 →</button></template></PageIntro><div class="metric-grid"><MetricCard label="目录模型" :value="models.length" :note="`活跃 ${activeModels.length}`" icon="▦"/><MetricCard label="Auto 可用" :value="autoModels.length" :note="`${models.length?Math.round(autoModels.length/models.length*100):0}% 覆盖`" tone="blue" icon="◎"/><MetricCard label="待复盘" :value="reviewStats.pending" note="等待教师模型" tone="amber" icon="✦"/><MetricCard label="Provider" :value="providers.length" note="已接入控制面" tone="green" icon="◫"/></div><div class="dashboard-grid"><article class="glass-card wide-card"><div class="card-title"><span>生产健康</span><StatusBadge :label="overview ? overviewHealthLabel(overview.health.overall as OverviewStatus) : '读取中'" :tone="overview ? overviewTone(overview.health.overall) : 'muted'"/></div><div class="health-line"><span class="pulse-dot" :class="{ 'pulse-dot-off': overview?.health.service.status !== 'ready' }"></span><strong>星枢服务</strong><span class="mono">{{ overview?.health.service.detail || '未知' }}</span><StatusBadge v-if="overview" :label="overviewHealthLabel(overview.health.service.status)" :tone="overviewTone(overview.health.service.status)"/></div><div class="health-line"><span class="pulse-dot" :class="{ 'pulse-dot-off': !overview?.consistency.ok }"></span><strong>目录一致性</strong><StatusBadge :label="overview ? (overview.consistency.ok ? '通过' : '需检查') : '未知'" :tone="overview ? (overview.consistency.ok ? 'green' : 'amber') : 'muted'"/></div></article><article class="glass-card"><div class="card-title"><span>学习闭环</span><StatusBadge :label="reviewer.model?'已配置':'待配置'" :tone="reviewer.model?'green':'amber'"/></div><div class="loop-steps"><span class="done">记录</span><i>→</i><span :class="reviewStats.reviewed?'done':'current'">复盘</span><i>→</i><span>知识</span><i>→</i><span>Shadow</span></div><p class="muted">{{reviewer.model?`教师：${reviewer.model}`:'未选择教师，只记录不复盘。'}}</p></article><article class="glass-card wide-card"><div class="card-title"><span>Provider 资源</span><button class="text-button" @click="navigate('resources')">查看全部 →</button></div><div class="provider-mini-grid"><div v-for="p in (overview?.providers || providers)" :key="p.id" class="provider-mini"><span class="model-avatar">{{p.id.slice(0,1).toUpperCase()}}</span><span><strong>{{p.id}}</strong><small>{{p.models}} 个模型</small></span><StatusBadge :label="p.status==='disabled'?'已停用':'已接入'" :tone="p.status==='disabled'?'red':'green'"/></div></div></article><article class="glass-card"><div class="card-title"><span>快速入口</span></div><button class="quick-action" @click="navigate('reviews')">配置教师复盘 <b>→</b></button><button class="quick-action" @click="navigate('routing')">查看 Auto 路由 <b>→</b></button><button class="quick-action" @click="navigate('system')">检查系统状态 <b>→</b></button><button class="quick-action" @click="navigate('logs')">最近调用 / 告警 <b>{{overview?.recent.count || 0}} / {{overview?.alerts.count || 0}}</b></button></article></div></section>
      <section v-else-if="page==='resources'" class="page-stack"><PageIntro kicker="PROVIDER POOL" title="资源池" description="接入和管理通用 OpenAI-compatible Provider；FreeLLMAPI 继续作为独立模块管理。"><template #actions><button class="button button-secondary" @click="sync">同步全部</button><button class="button button-primary" :disabled="!credentialKeyReady" @click="openProviderWizard()">＋ 添加 Provider</button></template></PageIntro><div v-if="!credentialKeyReady" class="wizard-warning"><strong>动态接入暂不可用</strong><p>未配置 XING_SHU_CREDENTIAL_KEY。环境变量 Provider 仍可使用，但动态 API Key 不允许明文保存。</p></div><div class="provider-grid"><article v-for="p in providers" :key="p.id" class="glass-card provider-card"><div class="provider-icon">{{p.id.slice(0,1).toUpperCase()}}</div><div><h3>{{providerRecord(p.id)?.name||p.id}}</h3><p>{{p.id}} · {{providerRecord(p.id)?.source==='environment'?'部署配置':providerRecord(p.id)?.source==='dynamic'?'动态接入':p.kind}}</p><small class="mono">{{p.last_sync ? `同步 ${p.last_sync}` : '尚未同步'}}</small></div><strong>{{p.models}}</strong><small>models</small><StatusBadge :label="providerOperationalLabel(p)" :tone="providerOperationalTone(p)"/><div class="provider-fact provider-key-fact"><span>API Key</span><strong>{{providerRecord(p.id)?.api_key_mask||'未配置'}}</strong><StatusBadge :label="providerRecord(p.id)?.read_only?'只读':'加密存储'" :tone="providerRecord(p.id)?.read_only?'muted':'green'"/></div><div v-if="p.cooldown_active" class="provider-fact">冷却至 {{p.cooldown_until || '未知'}}</div><div v-if="p.sync_error" class="provider-fact error-text">{{p.sync_error_type || 'sync_error'}}：{{p.sync_error}}</div><div class="provider-actions"><button class="button button-secondary button-small" @click="operate(`/api/admin/sync?id=${encodeURIComponent(p.id)}`,'确认同步 Provider',`将从 ${p.id} 重新读取模型目录。`)">同步模型</button><button v-if="providerRecord(p.id)" class="button button-ghost button-small" @click="openProviderWizard(providerRecord(p.id))">{{providerRecord(p.id)?.read_only?'重新验证':'编辑'}}</button><button v-if="providerRecord(p.id)&&!providerRecord(p.id)?.read_only&&providerRecord(p.id)?.enabled!==false" class="button button-ghost button-small" @click="providerRegistryAction(providerRecord(p.id)!,'disable')">停用</button><button v-if="providerRecord(p.id)&&!providerRecord(p.id)?.read_only&&providerRecord(p.id)?.enabled===false" class="button button-secondary button-small" @click="providerRegistryAction(providerRecord(p.id)!,'enable')">启用</button><button v-if="providerRecord(p.id)&&!providerRecord(p.id)?.read_only" class="button button-danger button-small" @click="providerRegistryAction(providerRecord(p.id)!,'delete')">删除</button><button class="button button-ghost button-small" @click="selected=p as unknown as Row">详情</button></div></article><article v-for="p in providerRegistry.filter(item=>!providers.some(current=>current.id===item.id))" :key="`offline-${p.id}`" class="glass-card provider-card provider-card-offline"><div class="provider-icon">{{p.id.slice(0,1).toUpperCase()}}</div><div><h3>{{p.name||p.id}}</h3><p>{{p.id}} · {{p.source==='environment'?'部署配置':'动态接入'}}</p><small class="mono">当前未进入运行配置</small></div><strong>0</strong><small>models</small><StatusBadge :label="p.enabled===false?'已停用':'离线'" :tone="p.enabled===false?'muted':'amber'"/><div class="provider-fact provider-key-fact"><span>API Key</span><strong>{{p.api_key_mask||'未配置'}}</strong><StatusBadge :label="p.read_only?'只读':'加密存储'" :tone="p.read_only?'muted':'green'"/></div><div class="provider-actions"><button class="button button-ghost button-small" @click="openProviderWizard(p)">{{p.read_only?'重新验证':'编辑'}}</button><button v-if="!p.read_only&&p.enabled===false" class="button button-secondary button-small" @click="providerRegistryAction(p,'enable')">启用</button><button v-if="!p.read_only" class="button button-danger button-small" @click="providerRegistryAction(p,'delete')">删除</button></div></article></div><ProviderWizard :open="providerWizardOpen" :provider="editingProvider" :credential-ready="credentialKeyReady" @close="closeProviderWizard" @saved="providerSaved"/></section>
      <section v-else-if="page==='integrations'" class="page-stack"><PageIntro kicker="EXTERNAL INTEGRATION" title="外部集成" description="FreeLLMAPI 是可选的外部本地服务；授权后星枢会直接只读读取其本地额度数据，不修改 FreeLLMAPI。"><template #actions><button class="button button-secondary button-small" @click="probeIntegration">只读探测</button><button v-if="!integration.authorized" class="button button-primary button-small" @click="authorizeIntegration">授权接入</button><button v-else class="button button-danger button-small" @click="revokeIntegration">撤销接入</button></template></PageIntro><div class="integration-grid"><article class="glass-card integration-card"><div class="card-title"><span>FreeLLMAPI</span><StatusBadge :label="String(integration.status||'未配置')" :tone="integration.usable?'green':integration.authorized?'amber':'muted'"/></div><div class="integration-facts"><div><span>来源</span><strong>本地外部集成</strong></div><div><span>实例</span><strong>{{value(integration,'id')||'freellmapi-local'}}</strong></div><div><span>地址</span><strong class="mono">{{value(integration,'endpoint')||'未配置'}}</strong></div><div><span>模型</span><strong>{{value(integration,'model_count')||0}}</strong></div><div><span>就绪上游</span><strong>{{value(integration,'ready_upstreams')||0}}</strong></div><div><span>本地额度</span><strong>{{integration.local_quota_state==='available'?'已读取':integration.local_quota_state==='stale'?'读取过期':integration.authorized?'暂无数据':'未授权'}}</strong></div></div><p class="muted">本地额度读取源：FreeLLMAPI SQLite/WAL，只读挂载；不读取密钥和请求内容。</p><div class="integration-switches"><button class="button button-secondary" :disabled="!integration.authorized" @click="toggleIntegrationRoute">{{integration.route_enabled?'关闭生产路由':'允许生产路由'}}</button><button class="button button-ghost" :disabled="!integration.authorized" @click="syncIntegration">同步模型和状态</button><button class="button button-ghost" :disabled="!integration.authorized" @click="refreshLocalQuota">刷新本地额度</button></div></article><article class="glass-card integration-card"><div class="card-title"><span>授权说明</span><StatusBadge :label="integration.authorized?'已授权':'未授权'" :tone="integration.authorized?'green':'amber'"/></div><p>授权接入后，星枢只读打开 FreeLLMAPI 的本地数据库，读取模型目录预算、本月模型使用量、速率限制使用量和 Provider 额度观测。</p><p>星枢不会改写 FreeLLMAPI 代码、数据库或 WAL，也不会复制下游 API Key、管理 Cookie、Prompt 或 Response。</p><p>生产路由开启后，请求才可能经 FreeLLMAPI 转发到它管理的下游 Provider。</p><div class="integration-meta"><span>目录同步：{{value(integration,'last_sync')||'未同步'}}</span><span>额度读取：{{value(integration,'local_quota_checked_at')||'未读取'}}</span><span>最近错误：{{value(integration,'last_error')||value(integration,'local_quota_error')||'无'}}</span></div></article></div><div v-if="integration.authorized && integration.local_quota" class="glass-card local-quota-panel"><div class="card-title"><span>FreeLLMAPI 本地额度总览</span><div class="integration-switches"><StatusBadge :label="integration.local_quota.partial?'部分可解释':'已读取'" :tone="integration.local_quota.partial?'amber':'green'"/><button class="button button-ghost button-small" @click="refreshLocalQuota">刷新</button></div></div><div class="metric-grid compact"><MetricCard label="模型预算" :value="formatTokens(integration.local_quota.totals.budget_tokens)"/><MetricCard label="本月已用" :value="formatTokens(integration.local_quota.totals.used_tokens)" tone="blue"/><MetricCard label="预计剩余" :value="formatTokens(integration.local_quota.totals.remaining_estimate)" tone="green"/><MetricCard label="本月请求" :value="String(integration.local_quota.totals.requests)" tone="amber"/></div><div class="local-quota-table"><div class="table-row table-head"><span>模型</span><span>预算</span><span>本月使用</span><span>预计剩余</span></div><div v-for="model in integration.local_quota.models" :key="`${model.platform}/${model.model_id}`" class="table-row"><span><strong>{{model.display_name||model.model_id}}</strong><small>{{model.platform}} · {{model.model_id}}</small></span><span>{{formatTokens(model.budget_tokens)}}</span><span>{{formatTokens(model.used_tokens)}}<small>{{model.requests}} requests</small></span><span>{{formatTokens(model.remaining_estimate)}}</span></div></div><p v-if="integration.local_quota.warnings?.length" class="muted">部分模型预算是文本标签或共享池，无法转换为绝对 Token 数：{{integration.local_quota.warnings.join('、')}}</p></div><div v-else-if="integration.authorized" class="glass-card unavailable-state"><StatusBadge label="本地额度暂不可用" tone="amber"/><p>{{integration.local_quota_error||'点击“刷新本地额度”重试；FreeLLMAPI 数据库不会被修改。'}}</p></div></section>
      <section v-else-if="page==='catalog'" class="page-stack"><PageIntro kicker="MODEL REGISTRY" title="模型目录" :count="`${filteredModels.length} / ${models.length}`" description="FreeLLMAPI 模型自动接入；其他 Provider 仅发现，必须在能力治理中由你明确批准后才进入路由。"><template #actions><button class="button button-secondary" @click="sync">同步目录</button></template></PageIntro><div class="toolbar glass-card"><label class="search-field"><span>⌕</span><input v-model="query" placeholder="搜索模型、Provider 或能力"/></label><select v-model="providerFilter"><option value="">全部 Provider</option><option v-for="p in providers" :key="p.id" :value="p.id">{{p.id}}</option></select><select v-model="statusFilter"><option value="">全部状态</option><option value="active">active</option><option value="unknown">unknown</option><option value="disabled">disabled</option></select><select v-model="capabilityFilter"><option value="all">全部能力</option><option value="tools">Tools</option><option value="vision">Vision</option><option value="structured_output">JSON 已验证</option><option value="unknown">JSON 未知</option></select></div><div class="batch-toolbar glass-card"><label><input type="checkbox" :checked="allPageSelected" @change="togglePageModels"/> 选择当前页</label><span>{{selectedModelIds.length}} 个模型已选</span><button class="button button-primary button-small" :disabled="!selectedModelIds.length || probeBatchBusy" @click="runProbeBatch">{{probeBatchBusy?'探测中…':'批量探测 JSON 能力'}}</button><span v-if="probeBatch" class="muted">{{probeBatch.completed}}/{{probeBatch.total}}，失败 {{probeBatch.failed}}</span></div><div class="model-table glass-card"><div class="table-row table-head"><span>模型 / Provider</span><span>状态</span><span>能力</span><span>Auto</span></div><div v-for="m in pagedModels" :key="`${m.provider}/${m.id}`" class="table-row model-selection-row"><input type="checkbox" :checked="selectedModelIds.includes(`${m.provider}/${m.id}`)" :disabled="m.status !== 'active'" @change="toggleModel(m)"/><button class="table-button model-row-button" @click="selected=m"><span><strong>{{m.id}}</strong><small>{{m.provider}}</small></span><StatusBadge :label="m.status" :tone="tone(m.status)"/><CapabilityChips :model="m"/><span :class="m.auto_routable?'text-green':'muted'">{{m.auto_routable?'可用':'—'}}</span></button></div><EmptyState v-if="!filteredModels.length" title="没有匹配模型" detail="调整筛选条件或同步 Provider 目录。" action="同步目录" @action="sync"/><Pagination :page="currentPage" :total="filteredModels.length" :page-size="pageSize" @change="currentPage=$event"/></div><div class="data-panel glass-card"><div class="panel-toolbar"><strong>能力探测历史</strong><span class="muted">{{probeHistory.length}} 批</span></div><div v-for="item in probeHistory.slice().reverse().slice(0,10)" :key="item.job_id" class="table-row"><span><strong>{{item.job_id}}</strong><small>{{item.started_at}}</small></span><StatusBadge :label="item.status" :tone="item.failed ? 'amber' : 'green'"/><span>{{item.completed}}/{{item.total}}</span><span>失败 {{item.failed}}</span></div><EmptyState v-if="!probeHistory.length" title="暂无探测历史" detail="选择活跃模型后运行批量 JSON 能力探测。"/></div></section>
      <section v-else-if="page==='routing'" class="page-stack"><PageIntro kicker="ROUTING CENTER" title="路由中心" description="输入一条真实请求，查看需求特征、候选资格、排除原因和分数分解；Explain 只读，不修改路由策略。"><template #actions><button class="button button-primary" :disabled="explainBusy" @click="explainRoute">{{explainBusy?'分析中…':'运行 Explain'}}</button></template></PageIntro><div class="explain-grid"><article class="glass-card"><div class="card-title"><span>请求输入</span><span class="muted">JSON · 最大 256KB</span></div><textarea v-model="explainInput" class="explain-input" spellcheck="false" aria-label="路由 Explain 请求 JSON"></textarea><button class="button button-primary" :disabled="explainBusy" @click="explainRoute">{{explainBusy?'分析中…':'分析这条请求'}}</button></article><article class="glass-card"><div class="card-title"><span>决策摘要</span><StatusBadge v-if="explainResult" :label="String(explainResult.need || 'general')" tone="blue"/></div><div v-if="explainResult" class="decision-summary"><strong>{{value(explainResult,'selected')||'没有可用候选'}}</strong><span>{{value(explainResult,'excluded')}} 个候选被排除</span></div><EmptyState v-else title="尚未运行 Explain" detail="输入真实请求后，系统会展示请求级决策证据。"/></article></div><div v-if="explainResult" class="data-panel glass-card"><div class="panel-toolbar"><strong>候选排名与分数分解</strong><span class="muted">{{(explainResult.candidates as Row[] || []).length}} 个候选</span></div><div v-for="(candidate,index) in (explainResult.candidates as Row[] || [])" :key="`${value(candidate,'provider')}/${value(candidate,'model')}`" class="table-row route-explain-row"><span><strong>#{{index+1}} {{value(candidate,'model')}}</strong><small>{{value(candidate,'provider')}}</small></span><StatusBadge :label="candidate.eligible?'可选':'已排除'" :tone="candidate.eligible?'green':'red'"/><span class="score">{{value(candidate,'total_score')}}</span><small>{{(candidate.reasons as string[] || []).join(' · ') || '满足基础资格'}}</small><button class="button button-ghost button-small" @click="selected=candidate">分数详情</button></div></div><div class="data-panel glass-card"><div class="panel-toolbar"><strong>Auto 候选基线</strong><span class="muted">{{routes.length}} 条 · GET 兼容视图</span></div><button v-for="r in routes.slice(0,80)" :key="`${value(r,'provider')}/${value(r,'model')}`" class="table-row table-button route-row" @click="selected=r"><span><strong>{{value(r,'model')}}</strong><small>{{value(r,'provider')}}</small></span><StatusBadge :label="value(r,'status')" :tone="tone(value(r,'status'))"/><span class="score">{{value(r,'rule_score')}}</span><span :class="r.knowledge_applied?'text-green':'muted'">{{r.knowledge_applied?'知识命中':'基础规则'}}</span></button><EmptyState v-if="!routes.length" title="暂无路由数据" detail="请先同步模型目录。" action="同步目录" @action="sync"/></div></section>
      <section v-else-if="page==='governance'" class="page-stack"><PageIntro kicker="CAPABILITY GOVERNANCE" title="能力治理" description="FreeLLMAPI 自动接入；其他 Provider 的模型需由你明确批准后才进入 Auto。"/><div class="metric-grid compact"><MetricCard v-for="s in ['active','unknown','meta','stale','retired','disabled']" :key="s" :label="s" :value="governanceStateCounts[s as keyof typeof governanceStateCounts]" :tone="tone(s)"/></div><div class="toolbar glass-card"><label class="search-field"><span>⌕</span><input v-model="query" class="compact-input" placeholder="筛选模型、状态或原因"/></label><select v-model="statusFilter"><option value="">全部治理状态</option><option v-for="s in ['active','unknown','meta','stale','retired','disabled']" :key="s" :value="s">{{s}}</option></select></div><div class="data-panel glass-card"><div class="panel-toolbar"><strong>治理记录</strong><span class="muted">{{governance.length}} 条 · 点击查看 Auto 资格和证据</span></div><div v-for="r in governance.filter(r=>(!query||JSON.stringify(r).toLowerCase().includes(query.toLowerCase()))&&(!statusFilter||value(r,'status')===statusFilter)).slice(0,120)" :key="value(r,'key')" class="table-row governance-row"><button class="table-button" @click="selected=r"><span><strong>{{value(r,'key')}}</strong><small>{{value(r,'reason')}}</small></span><StatusBadge :label="value(r,'status')" :tone="tone(value(r,'status'))"/><span>{{value(r,'model')==='—'?'目录事实':'模型能力'}}</span><span class="muted">{{value(r,'checked_at')}}</span></button><template v-if="governanceModel(r)"><button class="button button-secondary button-small" @click="previewGovernance(governanceModel(r)!, !governanceModel(r)!.auto_routable)">预览 {{governanceModel(r)!.auto_routable?'拒绝':'允许'}}</button></template></div><EmptyState v-if="!governance.length" title="暂无治理记录" detail="当前接口没有返回治理数据。"/></div><div v-if="governancePreview" class="glass-card governance-preview"><div class="card-title"><span>治理变更预览</span><StatusBadge label="dry-run" tone="amber"/></div><div v-for="change in (governancePreview.changes as Row[] || [])" :key="value(change,'key')" class="preview-row"><span><strong>{{value(change,'key')}}</strong><small>{{change.changed?'将发生变更':'无变更'}}</small></span><span>{{value(change,'before')}} → {{value(change,'after')}}</span></div><button class="button button-primary button-small" :disabled="governanceBusy" @click="applyGovernance">确认应用</button></div></section>
      <section v-else-if="page==='reviews'" class="page-stack"><PageIntro kicker="TEACHER LOOP" title="教师复盘" description="白天记录，夜间批量复盘。教师模型必须先通过结构化输出能力验证。"><template #actions><div class="intro-actions"><StatusBadge :label="reviewer.available?'复盘已就绪':reviewer.model?'教师能力待恢复':'等待配置'" :tone="reviewer.available?'green':reviewer.model?'amber':'amber'"/><button class="button button-secondary button-small" :disabled="!reviewer.model||reviewerTestBusy" @click="testReviewer">{{reviewerTestBusy?'测试中…':'测试教师连接'}}</button><button class="button button-primary button-small" :disabled="!reviewer.available||reviewRunning" @click="runReview">{{reviewRunning?'复盘中…':'运行批次'}}</button><button class="button button-ghost button-small" :disabled="reviewPruning" @click="operate('/api/admin/reviews/prune?days=30','确认清理复盘记录','将删除超过 30 天的复盘和 Shadow 记录。',true,'清理记录')">{{reviewPruning?'清理中…':'清理旧记录'}}</button></div></template></PageIntro><div class="metric-grid compact"><MetricCard label="待复盘" :value="reviewStats.pending" note="等待批次" tone="amber"/><MetricCard label="已复盘" :value="reviewStats.reviewed" note="已有结论" tone="green"/><MetricCard label="失败" :value="reviewStats.failed" note="可重试" tone="red"/><MetricCard label="候选教师" :value="candidates.eligible" :note="`待探测 ${candidates.probeable}`" tone="blue"/></div><div v-if="reviewerTest" class="glass-card reviewer-test-result"><div class="card-title"><span>教师连接诊断</span><StatusBadge :label="reviewerTest.structured_output?'通过':'未通过'" :tone="reviewerTest.structured_output?'green':'red'"/></div><div class="health-line"><strong>网络</strong><StatusBadge :label="reviewerTest.network?'通过':'失败'" :tone="reviewerTest.network?'green':'red'"/><span class="mono">{{value(reviewerTest,'latency_ms')}} ms</span></div><div class="health-line"><strong>鉴权 / HTTP</strong><StatusBadge :label="reviewerTest.auth && reviewerTest.http?'通过':'失败'" :tone="reviewerTest.auth&&reviewerTest.http?'green':'red'"/><span class="muted">{{value(reviewerTest,'error_type')}}</span></div><div class="health-line"><strong>JSON / 结构化</strong><StatusBadge :label="reviewerTest.json&&reviewerTest.structured_output?'通过':'失败'" :tone="reviewerTest.json&&reviewerTest.structured_output?'green':'red'"/><span class="muted">{{value(reviewerTest,'error')}}</span></div></div><div v-if="candidates.items.length" class="candidate-grid"><article v-for="m in candidates.items" :key="m.id" class="candidate-card glass-card"><div class="candidate-top"><div class="model-avatar">{{m.id.slice(0,1).toUpperCase()}}</div><div><strong>{{m.id}}</strong><small>{{m.provider}}</small></div><StatusBadge label="可用" tone="green"/></div><CapabilityChips :model="m"/><div class="candidate-evidence"><span>结构化输出</span><b>已验证</b><small>{{m.capability_evidence?.structured_output?.source||'能力证据'}}</small></div><button class="button button-primary" @click="choose(m)">{{reviewer.model===m.id?'当前教师':'选择为教师'}}</button></article></div><div v-else class="glass-card"><EmptyState title="当前没有可直接选择的教师模型" :detail="`已排除 ${candidates.excluded} 个模型；其中 ${candidates.probeable} 个可以探测。`" action="重新检查资格" @action="boot"/><div class="probe-list"><div v-for="m in candidates.probe_candidates.slice(0,16)" :key="m.id" class="probe-row"><span><strong>{{m.id}}</strong><small>{{m.provider}}</small></span><StatusBadge label="能力未知" tone="amber"/><button class="button button-secondary button-small" @click="probe(m)">探测 JSON</button></div></div></div><div class="data-panel glass-card"><div class="panel-toolbar"><strong>复盘记录</strong><span class="muted">{{reviews.filter(r=>!reviewStatusFilter||r.review_status===reviewStatusFilter).length}} / {{reviewTotal}} 条</span><select v-model="reviewStatusFilter" class="compact-input"><option value="">全部状态</option><option value="pending">pending</option><option value="processing">processing</option><option value="reviewed">reviewed</option><option value="failed">failed</option><option value="skipped">skipped</option></select></div><button v-for="r in reviews.filter(r=>!reviewStatusFilter||r.review_status===reviewStatusFilter)" :key="r.id" class="review-row review-row-button" @click="openReviewDetail(r)"><span><strong>{{r.model}}</strong><small>{{r.provider}} · {{r.batch_id||'未分批'}}</small></span><StatusBadge :label="r.review_status" :tone="tone(r.review_status)"/><span>{{r.recommended_model||'等待结论'}}</span><span class="muted">{{r.review_error||r.conclusion||'—'}}</span></button><EmptyState v-if="!reviews.length" title="暂无复盘记录" detail="当前没有可展示的摘要记录。"/><Pagination :page="Math.floor(reviewOffset/reviewLimit)+1" :total="reviewTotal" :page-size="reviewLimit" @change="reviewOffset=($event-1)*reviewLimit; boot()"/></div><div class="data-panel glass-card"><div class="panel-toolbar"><strong>批次历史</strong><span class="muted">{{reviewBatches.length}} 个批次</span></div><div v-for="batch in reviewBatches" :key="batch.batch_id" class="batch-row"><span><strong>{{batch.batch_id}}</strong><small>{{batch.models.join(', ')}}</small></span><span>{{batch.total}} 条</span><StatusBadge :label="`${batch.reviewed} 已完成 / ${batch.failed} 失败`" :tone="batch.failed?'amber':'green'"/><span class="muted">{{batch.last_error||'—'}}</span></div><EmptyState v-if="!reviewBatches.length" title="暂无批次历史" detail="运行复盘批次后，处理统计会保留在这里。"/></div></section>
      <section v-else-if="page==='knowledge'" class="page-stack"><PageIntro kicker="ROUTING KNOWLEDGE" title="路由知识" description="从已复盘记录生成候选知识；状态、验证历史和源复盘记录可追溯，不直接改写 Auto。"><template #actions><button class="button button-primary" @click="operate('/api/admin/knowledge/build')">构建候选知识</button></template></PageIntro><div class="toolbar glass-card"><span class="muted">状态筛选</span><select v-model="knowledgeStatusFilter" @change="boot"><option value="">全部状态</option><option value="proposed">proposed</option><option value="validated">validated</option><option value="trusted">trusted</option><option value="rejected">rejected</option><option value="expired">expired</option></select><span class="muted">{{knowledge.length}} 条</span></div><div class="data-panel glass-card"><div class="panel-toolbar"><strong>知识条目</strong><span class="muted">只有 trusted Knowledge 才能运行 Shadow</span></div><div v-for="k in knowledge" :key="k.id" class="knowledge-row"><span><strong>{{k.signature}}</strong><small>{{k.id}} · 推荐：{{k.recommended_model}} · 源复盘 {{k.source_review_ids?.length||0}} 条</small></span><StatusBadge :label="k.status" :tone="tone(k.status)"/><span>{{k.samples}} 样本 / {{k.validated_samples}} 验证</span><span>{{k.validated_samples?Math.round(k.successful_samples/k.validated_samples*100)+'%':'—'}}<small>{{k.failure_cause||'无失败原因'}}</small></span><div class="row-actions"><button v-if="k.status==='proposed'" class="button button-secondary button-small" @click="validateKnowledge(k.id,true)">验证通过</button><button v-if="k.status==='validated'" class="button button-primary button-small" @click="decideKnowledge(k.id,'trusted')">设为可信</button><button v-if="k.status==='proposed'||k.status==='validated'||k.status==='trusted'" class="button button-ghost button-small" @click="decideKnowledge(k.id,'rejected')">否决</button><button v-if="k.status==='expired'||k.status==='rejected'" class="button button-secondary button-small" @click="restoreKnowledge(k.id)">恢复验证</button><button v-if="k.status==='trusted'" class="button button-secondary button-small" @click="runKnowledgeShadow(k)">运行 Shadow</button></div><details v-if="k.validation_history?.length||k.human_note" class="knowledge-history"><summary>验证历史 / 备注</summary><p v-if="k.human_note" class="muted">{{k.human_note}}</p><small v-for="v in k.validation_history" :key="v.id">{{v.id}} · {{v.success?'通过':'失败'}} · {{v.status_from}} → {{v.status_to}} · {{v.note||v.failure_cause||'—'}}</small></details></div><EmptyState v-if="!knowledge.length" title="暂无路由知识" detail="教师完成复盘后，可以从记录生成候选知识。" action="构建候选" @action="operate('/api/admin/knowledge/build')"/></div></section>
      <section v-else-if="page==='shadow'" class="page-stack"><PageIntro kicker="SHADOW REPLAY" title="影子验证" description="只校验协议、内容、结构化和工具调用兼容性，不执行外部副作用。必须明确选择 Knowledge、源复盘和候选模型。"><template #actions><button class="button button-secondary" @click="navigate('knowledge')">管理可信 Knowledge →</button></template></PageIntro><div class="glass-card shadow-selector"><div class="panel-toolbar"><strong>创建 Shadow 批次</strong><StatusBadge :label="selectedKnowledgeId?'已选择 Knowledge':'待选择'" :tone="selectedKnowledgeId?'green':'amber'"/></div><select v-model="selectedKnowledgeId"><option value="">选择 trusted Knowledge</option><option v-for="k in knowledge.filter(x=>x.status==='trusted')" :key="k.id" :value="k.id">{{k.signature}} · {{k.recommended_model}}</option></select><select v-model="selectedReviewId"><option value="">选择源复盘记录</option><option v-for="r in reviews.filter(x=>x.review_status==='reviewed'&&x.replayable)" :key="r.id" :value="r.id">{{r.id}} · {{r.model}} · {{r.conclusion||'已复盘'}}</option></select><select v-model="selectedCandidateModel"><option value="">使用 Knowledge 推荐模型</option><option v-for="m in activeModels.filter(x=>x.auto_routable)" :key="`${m.provider}/${m.id}`" :value="m.id">{{m.id}} · {{m.provider}}</option></select><button class="button button-primary" :disabled="!selectedKnowledgeId||!selectedReviewId||!selectedCandidateModel" @click="startShadowBatch">创建批次</button></div><div class="metric-grid compact"><MetricCard label="结果" :value="shadows.length"/><MetricCard label="成功" :value="shadows.filter(s=>s.success).length" tone="green"/><MetricCard label="失败" :value="shadows.filter(s=>s.status==='failed'||s.failure_cause).length" tone="red"/><MetricCard label="结构化通过" :value="shadows.filter(s=>s.structured_ok).length" tone="blue"/></div><div class="data-panel glass-card"><div class="panel-toolbar"><strong>批次历史</strong><span class="muted">{{shadowBatches.length}} 批</span></div><div v-for="b in shadowBatches" :key="b.id" class="batch-row"><span><strong>{{b.id}}</strong><small>{{b.knowledge_id}} · {{b.candidate_model}}</small></span><span>{{b.completed}}/{{b.total}}</span><StatusBadge :label="b.status" :tone="tone(b.status)"/><button v-if="b.status==='pending'||b.status==='running'" class="button button-ghost button-small" @click="stopShadowBatch(b.id)">停止</button><button v-if="b.status==='failed'||b.status==='stopped'" class="button button-secondary button-small" @click="retryShadowBatch(b.id)">重试</button><span class="muted">成功 {{b.succeeded}} · 失败 {{b.failed}} · 停止 {{b.stopped}} · {{b.last_error||'—'}}</span></div><EmptyState v-if="!shadowBatches.length" title="暂无 Shadow 批次" detail="选择可信 Knowledge、源复盘和候选模型后创建批次。"/></div><div class="data-panel glass-card"><div class="panel-toolbar"><strong>结果详情</strong><span class="muted">semantic_match 为 token 重叠启发式，不是独立语义裁判</span></div><div v-for="s in shadows" :key="s.id||`${s.candidate_model}-${s.latency_ms}`" class="table-row"><span><strong>{{s.candidate_model}}</strong><small>{{s.knowledge_id}} · {{s.review_id}} · {{s.batch_id||'单次'}}</small></span><StatusBadge :label="s.status" :tone="tone(s.status)"/><span>HTTP {{s.http_status||'—'}} · {{s.latency_ms}} ms</span><span>{{s.protocol_ok?'协议 ✓':'协议 —'}} · {{s.structured_ok?'JSON ✓':'JSON —'}} · {{s.tool_compatible?'Tools ✓':'Tools —'}}</span><span class="muted">{{s.failure_cause||s.error||s.quality_conclusion||'—'}}</span></div><EmptyState v-if="!shadows.length" title="暂无 Shadow 结果" detail="创建批次后，结果会出现在这里。"/></div></section>
      <section v-else-if="page==='logs'" class="page-stack"><PageIntro kicker="OBSERVABILITY" title="调用与告警" description="按模型、Provider、状态和延迟筛选调用审计；原始记录只读展示。"/><div class="toolbar glass-card"><label class="search-field"><span>⌕</span><input v-model="query" placeholder="筛选模型"/></label><select v-model="auditProviderFilter" @change="boot"><option value="">全部 Provider</option><option v-for="p in providers" :key="p.id" :value="p.id">{{p.id}}</option></select><select v-model="auditStatusFilter" @change="boot"><option value="">全部状态</option><option value="200">200</option><option value="429">429</option><option value="500">500</option></select><input v-model="auditMinLatency" type="number" min="0" placeholder="最小 ms" @change="boot"/><input v-model="auditMaxLatency" type="number" min="0" placeholder="最大 ms" @change="boot"/><button class="button button-ghost button-small" @click="auditProviderFilter='';auditStatusFilter='';auditMinLatency='';auditMaxLatency='';query='';boot()">清除筛选</button></div><div class="data-panel glass-card"><div class="panel-toolbar"><strong>最近调用</strong><span class="muted">{{recent.length}} 条当前页</span></div><button v-for="r in recent.filter(r=>!query||JSON.stringify(r).toLowerCase().includes(query.toLowerCase())).slice(0,100)" :key="`${value(r,'time')}-${value(r,'model')}-${value(r,'request_id')}`" class="table-row table-button" @click="selected=r"><span><strong>{{value(r,'model')}}</strong><small>{{value(r,'provider')}} · {{value(r,'time')||value(r,'recorded_at')}}</small></span><StatusBadge :label="value(r,'status')" :tone="tone(value(r,'status'))"/><span>{{value(r,'latency_ms')}} ms</span><span>{{value(r,'tools')==='true'?'Tools':''}} {{value(r,'stream')==='true'?'Stream':''}}</span></button><EmptyState v-if="!recent.length" title="暂无匹配调用" detail="调整模型、Provider、状态或延迟筛选。"/></div></section>
      <section v-else-if="page==='accounts'" class="page-stack"><PageIntro kicker="ACCOUNT & QUOTA" title="账号额度" description="显示真实 Provider 额度；接口没有提供的字段明确标记为暂无数据，不以 0 伪造数据。"><template #actions><div class="intro-actions"><StatusBadge :label="quotaStatus.available?'额度可用':'额度 unavailable'" :tone="quotaStatus.available?'green':'amber'"/><button class="button button-secondary button-small" :disabled="!quotaStatus.configured" @click="operate('/api/admin/quota/refresh','刷新额度数据','只读取已授权集成提供的额度事实，不修改路由。')">刷新额度</button></div></template></PageIntro><div v-if="integration.authorized && integration.local_quota" class="glass-card local-quota-panel"><div class="card-title"><span>FreeLLMAPI 本地额度</span><div class="integration-switches"><StatusBadge :label="integration.local_quota_state==='stale'?'读取过期':integration.local_quota.partial?'部分可解释':'已读取'" :tone="integration.local_quota_state==='stale'||integration.local_quota.partial?'amber':'green'"/><button class="button button-ghost button-small" @click="refreshLocalQuota">刷新</button></div></div><div class="metric-grid compact"><MetricCard label="模型预算" :value="formatTokens(integration.local_quota.totals.budget_tokens)"/><MetricCard label="本月已用" :value="formatTokens(integration.local_quota.totals.used_tokens)" tone="blue"/><MetricCard label="预计剩余" :value="formatTokens(integration.local_quota.totals.remaining_estimate)" tone="green"/><MetricCard label="本月请求" :value="String(integration.local_quota.totals.requests)" tone="amber"/></div><div class="local-quota-table"><div class="table-row table-head"><span>模型 / Provider</span><span>预算</span><span>本月使用</span><span>预计剩余</span></div><div v-for="model in integration.local_quota.models" :key="`${model.platform}/${model.model_id}`" class="table-row"><span><strong>{{model.display_name||model.model_id}}</strong><small>{{model.platform}} · {{model.model_id}}</small></span><span>{{formatTokens(model.budget_tokens)}}</span><span>{{formatTokens(model.used_tokens)}}<small>{{model.requests}} requests</small></span><span>{{formatTokens(model.remaining_estimate)}}</span></div></div><p v-if="integration.local_quota.warnings?.length" class="muted">无法转换为绝对 Token 的预算保留原始标签并标记部分可解释。</p></div><div v-else-if="integration.authorized && integration.local_quota_state!=='available'" class="glass-card unavailable-state"><StatusBadge label="FreeLLMAPI 本地额度暂不可用" tone="amber"/><p>{{integration.local_quota_error||'授权后可刷新 FreeLLMAPI 本地 SQLite 额度数据。'}}</p></div><div class="data-panel glass-card"><div v-if="!quota.length" class="unavailable-state"><StatusBadge label="暂无 Provider 额度数据" tone="amber"/><p>当前 Provider 没有提供可验证的余额、使用量或重置时间接口。</p></div><div v-for="r in quota" :key="JSON.stringify(r)" class="table-row"><span><strong>{{value(r,'provider')}}</strong><small>{{value(r,'state')}} · {{value(r,'checked_at')}}</small></span><span>{{value(r,'remaining')}}</span><span>{{value(r,'used')}}</span><span>{{value(r,'reset_at')}}</span></div><div v-if="accounts.length" class="subsection"><strong>账号配置状态</strong><div v-for="r in accounts" :key="JSON.stringify(r)" class="table-row"><span><strong>{{value(r,'provider')}}</strong></span><span>{{value(r,'state')}}</span><span>{{value(r,'configured')}}</span></div></div><div class="subsection"><div class="card-title"><strong>额度历史</strong><span class="muted">{{quotaHistory.length?`${quotaHistory.length} 条事实`:'Provider 未提供可验证的额度历史'}}</span></div><div v-for="r in quotaHistory.slice(-20).reverse()" :key="JSON.stringify(r)" class="table-row"><span><strong>{{value(r,'provider')}}</strong><small>{{value(r,'checked_at')}}</small></span><span>{{value(r,'remaining')}}</span><span>{{value(r,'state')}}</span><span>{{value(r,'reset_at')}}</span></div><EmptyState v-if="!quotaHistory.length" title="暂无额度趋势" detail="Provider 没有提供可验证的额度历史，不显示伪造趋势。"/></div><EmptyState v-if="!quota.length&&!accounts.length" title="暂无账号额度数据" detail="账号管理和额度接口当前没有返回业务数据。"/></div></section>
      <section v-else-if="page==='snapshots'" class="page-stack"><PageIntro kicker="VERSION SNAPSHOTS" title="版本快照" description="保存当前目录状态；查看哈希、模型数量和差异，恢复操作保持 dry-run。"><template #actions><button class="button button-primary" @click="operate('/api/admin/snapshots/save')">保存快照</button></template></PageIntro><div class="snapshot-grid"><article v-for="file in snapshots" :key="file" class="snapshot-card glass-card"><button class="snapshot-open" @click="openSnapshotDetail(file)"><span class="snapshot-icon">◇</span><strong>{{file}}</strong><small>查看元数据 / 差异</small></button><button class="button button-secondary button-small" @click="confirmAction('预览快照恢复？',`将读取 ${file} 并返回 dry-run 结果，不会覆盖生产。`,()=>restoreSnapshot(file))">预览恢复</button></article></div><div v-if="snapshotDetail" class="glass-card"><div class="card-title"><span>{{value(snapshotDetail,'name')}}</span><StatusBadge label="dry-run" tone="amber"/></div><div class="detail-field"><span>SHA256</span><strong>{{value(snapshotDetail,'sha256')}}</strong></div><div class="detail-field"><span>快照模型</span><strong>{{value(snapshotDetail,'models')}} · 当前 {{value(snapshotDetail,'current_models')}} · 差异 {{value(snapshotDetail,'model_delta')}}</strong></div><div class="detail-field"><span>文件大小</span><strong>{{value(snapshotDetail,'bytes')}} bytes</strong></div></div><EmptyState v-if="!snapshots.length" title="暂无快照" detail="保存一次快照后，系统会在这里列出版本文件。"/></section>
      <section v-else-if="page==='operations'" class="page-stack"><PageIntro kicker="OPERATIONS" title="运维控制" description="高影响操作集中管理；Provider 同步、冷却和告警处理都会显示真实结果。"/><div class="operation-grid"><article class="glass-card operation-card"><span class="operation-icon">↻</span><h3>同步全部 Provider</h3><p>刷新模型目录，保留目录下降保护。</p><button class="button button-primary" @click="sync">执行同步</button></article><article class="glass-card operation-card"><span class="operation-icon">◌</span><h3>清除冷却</h3><p>只清除 Provider 冷却状态，不修改模型治理。</p><button class="button button-secondary" @click="operate('/api/admin/cooldowns/clear')">清除冷却</button></article><article class="glass-card operation-card"><span class="operation-icon">!</span><h3>告警状态</h3><p>{{alerts.length?'存在待处理告警':'当前没有返回告警'}}</p><StatusBadge :label="alerts.length?'请查看':'正常'" :tone="alerts.length?'amber':'green'"/></article></div><div class="toolbar glass-card"><select v-model="alertStatusFilter" @change="boot"><option value="">全部处理状态</option><option value="open">open</option><option value="acknowledged">acknowledged</option><option value="ignored">ignored</option><option value="resolved">resolved</option></select><select v-model="alertLevelFilter" @change="boot"><option value="">全部等级</option><option value="critical">critical</option><option value="warning">warning</option><option value="info">info</option></select><button class="button button-ghost button-small" @click="alertStatusFilter='';alertLevelFilter='';boot()">清除筛选</button></div><div class="data-panel glass-card"><div class="panel-toolbar"><strong>告警处理</strong><span class="muted">{{alerts.length}} 条</span></div><div v-for="a in alerts" :key="value(a,'id')" class="alert-row"><span><strong>{{value(a,'message')}}</strong><small>{{value(a,'level')}} · {{value(a,'handling_status')}} · {{value(a,'at')||value(a,'time')}}</small></span><StatusBadge :label="value(a,'handling_status')" :tone="value(a,'handling_status')==='resolved'?'green':value(a,'handling_status')==='ignored'?'muted':'amber'"/><button v-if="value(a,'handling_status')==='open'" class="button button-secondary button-small" @click="handleAlert(value(a,'id'),'acknowledge')">确认</button><button v-if="value(a,'handling_status')!=='resolved'" class="button button-primary button-small" @click="handleAlert(value(a,'id'),'resolve')">恢复</button><button v-if="value(a,'handling_status')==='open'" class="button button-ghost button-small" @click="handleAlert(value(a,'id'),'ignore')">忽略</button></div><EmptyState v-if="!alerts.length" title="暂无匹配告警" detail="当前筛选没有待处理告警。"/></div></section>
      <section v-else class="page-stack"><PageIntro kicker="SYSTEM STATUS" title="系统状态" description="把健康、版本、一致性、Watchdog 和运行态存储放在同一个生产检查面板。"/><div class="metric-grid compact"><MetricCard label="目录" :value="value(status,'current_catalog')"/><MetricCard label="Auto" :value="value(status,'auto_routable')" tone="blue"/><MetricCard label="一致性" :value="value(consistency,'ok')" :tone="consistency.ok?'green':'amber'"/><MetricCard label="Watchdog" :value="watchdog.healthy===true?'健康':value(watchdog,'consecutive_failures')||'未知'" :tone="watchdog.healthy===true?'green':'amber'"/></div><div class="system-grid"><article class="glass-card"><div class="card-title"><span>服务探针</span><StatusBadge label="已验证" tone="green"/></div><div class="health-line"><span class="pulse-dot"></span><strong>星枢服务</strong><span class="mono">12100 / health</span></div><div class="health-line"><strong>Watchdog</strong><StatusBadge :label="watchdog.healthy===true?'健康':value(watchdog,'detail')||'未知'" :tone="watchdog.healthy===true?'green':'amber'"/><span class="mono">失败 {{value(watchdog,'consecutive_failures')}}/{{value(watchdog,'max_failures')}}</span></div></article><article class="glass-card"><div class="card-title"><span>目录一致性</span><StatusBadge :label="consistency.ok?'通过':'需检查'" :tone="consistency.ok?'green':'amber'"/></div><pre class="compact-json">{{JSON.stringify(consistency,null,2)}}</pre></article></div><div class="data-panel glass-card"><div class="panel-toolbar"><strong>运行态存储</strong><span class="muted">{{(diagnostics.items as Row[]||[]).length}} 个文件</span></div><div v-for="item in (diagnostics.items as Row[]||[])" :key="value(item,'name')" class="table-row"><span><strong>{{value(item,'name')}}</strong><small>{{value(item,'updated_at')}}</small></span><span>{{item.exists?`${value(item,'bytes')} bytes`:'不存在'}}</span><span>{{item.records?`${value(item,'records')} records`:value(item,'error')}}</span><StatusBadge :label="item.exists?'可读':'未创建'" :tone="item.exists?'green':'muted'"/></div><EmptyState v-if="!diagnostics.items" title="暂无运行态指标" detail="诊断接口暂未返回数据。"/></div></section>
    <div v-if="paletteOpen" class="palette-layer" @click.self="closePalette"><section class="palette glass-card" role="dialog" aria-modal="true" aria-label="Command Palette"><div class="palette-head"><strong>Command Palette</strong><button class="button button-ghost button-small" @click="closePalette">Esc</button></div><input v-model="paletteQuery" autofocus placeholder="搜索页面或快捷操作…" aria-label="搜索页面"/><button v-for="([key,label]) in paletteItems" :key="key" class="palette-item" @click="choosePalette(key)"><span>{{label}}</span><small>{{key}}</small></button><EmptyState v-if="!paletteItems.length" title="没有匹配项" detail="输入页面名称或功能关键词。"/></section></div></template><DetailDrawer :open="!!selected" :title="selectedTitle()" subtitle="生产数据详情" @close="selected=null"><div v-if="selectedDomainModel" class="domain-detail"><section><div class="detail-section-title">身份与路由</div><div class="detail-field"><span>模型</span><strong>{{selectedDomainModel.id}}</strong></div><div class="detail-field"><span>Provider</span><strong>{{selectedDomainModel.provider}}</strong></div><div class="detail-field"><span>状态</span><strong>{{selectedDomainModel.status}}</strong></div><div class="detail-field"><span>Auto</span><strong>{{selectedDomainModel.auto_routable?'可用':'不可用'}}</strong></div></section><section><div class="detail-section-title">能力证据</div><div v-for="item in selectedModelEvidence" :key="item.capability" class="evidence-row"><span>{{item.capability}}</span><StatusBadge v-if="item.evidence" :label="item.evidence.supported?'支持':'不支持'" :tone="item.evidence.supported?'green':'red'"/><StatusBadge v-else label="未知" tone="amber"/><small>{{item.evidence ? `${item.evidence.source} · ${item.evidence.checked_at || '时间未知'}` : '没有已验证证据，不作推断'}}</small></div></section><section><div class="detail-section-title">Auto 排除原因</div><div v-if="selectedModelReasons.length" class="reason-list"><span v-for="reason in selectedModelReasons" :key="reason">{{reason}}</span></div><p v-else class="muted">当前没有已知排除原因。</p></section></div><StructuredDetail v-else :value="(selected as Row)||{}"/></DetailDrawer><ConfirmDialog :open="confirmOpen" :title="confirmTitle" :detail="confirmDetail" :confirm-label="confirmLabel" :danger="confirmDanger" :busy="confirmBusy" @confirm="acceptConfirm" @cancel="cancelConfirm"/><transition name="toast"><button v-if="toast" class="toast" @click="toast=''">✓ {{toast}}</button></transition></div></main></div>
</template>
